      ('public.mcp_authorize_approve(text,bytea,text,bytea)', 'bddeb78139828a444715cc77d4482d78'),
      ('public.mcp_authorize_view(text,bytea)', '18bd5cc8788ff45288733b57ce9d4d65')) x(sig, want) LOOP
