    RAISE EXCEPTION 'BACKLOG-4263 T-N: the mcp_settings row is missing';
  ELSIF v = 1 THEN
    PERFORM set_config('t4263n.bumped', 'on', true);
  ELSIF v <> 2 THEN
    RAISE EXCEPTION 'BACKLOG-4263 T-N: mcp_settings.notice_version is %, expected 1 or 2', v;  /*BUMP:refuse*/
  END IF;
END
$bump4263n$
$sm6_0$);
