  IF (v ->> 'functions_left')::int <> 0 OR (v ->> 'triggers_left')::int <> 0
     OR (v ->> 'live_pending')::int <> 0 OR (v ->> 'other_functions_changed')::int <> 0 OR (v ->> 'ledger')::int <> 0 THEN
    RAISE EXCEPTION 'ROLLBACK POST-CHECK 20261123150000 FAILED, nothing changed: %', v;
  END IF;
