    v := coalesce(((SELECT md5(p.prosrc) FROM pg_catalog.pg_proc p WHERE p.oid = pg_catalog.to_regprocedure('public._mcp_notice_change_expires_requests()')) IS DISTINCT FROM 'c6c5cc1976da55e4cb896e0f6e8ca2fb'), false);
    RAISE EXCEPTION 'undo-proof';
  EXCEPTION WHEN OTHERS THEN
