$controls4263n$;
DO $samples4263n$
DECLARE sv jsonb; sacc jsonb; sreads jsonb; sl jsonb;
BEGIN
  -- answers the portal reads, taken once against T-N's text (undone): the view at version 2, the AI-apps reader, the
  -- read log after one list call. The portal's test fixtures are transcribed from these (ids and nonces replaced there).
  BEGIN
    PERFORM pg_temp.tn();
    PERFORM pg_temp.begin_req('SMP', 'chatgpt');
    sv := pg_temp.view_req('SMP', 'A');
    PERFORM pg_temp.approve_req('SMP', 'A');
    PERFORM pg_temp.exchange_req('SMP', 'chatgpt');
    sl := pg_temp.lst('SMP', 'dA');
    sacc := pg_temp.as_user0('A', 'mcp_list_my_connection_access');
    sreads := pg_temp.as_user('A', 'mcp_list_my_message_reads', '%L, %L::integer', NULL, '50');
    RAISE EXCEPTION 'undo-sample';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM <> 'undo-sample' THEN sv := jsonb_build_object('error', SQLERRM); END IF;
  END;
  PERFORM pg_temp.rec('sample_view_v2', sv);
  PERFORM pg_temp.rec('sample_access', sacc);
  PERFORM pg_temp.rec('sample_reads', sreads);
  PERFORM pg_temp.rec('sample_list_ok', to_jsonb(sl ->> 'ok'));
  PERFORM pg_temp.rec('sample_ids', jsonb_build_object('A', pg_temp.s('A'), 'K1', pg_temp.s('K1'), 'dA', pg_temp.s('dA')));
END
$samples4263n$;
-- ================================================================ T-N at top level, then the rollback file, verbatim
DO $rb4263n$
DECLARE r text;
BEGIN
  IF to_regclass('pg_temp.t_out') IS NULL THEN
    RAISE EXCEPTION 'harness-n must run as one transaction (pg_temp.t_out is gone); the rollback step did not run';
  END IF;
  PERFORM pg_temp.put_tx('variant', 'pristine');
  r := pg_temp.try('tn');
  PERFORM pg_temp.rec('top_apply', to_jsonb(r));
  r := CASE WHEN r = 'ok' THEN pg_temp.try('rb') ELSE 'not run: ' || r END;
  PERFORM pg_temp.rec('rollback', to_jsonb(r));
  PERFORM pg_temp.rec('rollback_restores', to_jsonb(pg_temp.fingerprint() = (SELECT v #>> '{}' FROM pg_temp.t_out WHERE k = 'baseline_fp')));
END
$rb4263n$;
DO $end4263n$
BEGIN
  PERFORM pg_temp.rec('t_end', to_jsonb(clock_timestamp()));
  PERFORM pg_temp.rec('wal_bytes', to_jsonb(pg_catalog.pg_wal_lsn_diff(pg_catalog.pg_current_wal_insert_lsn(),
                                                                       ((SELECT v #>> '{}' FROM pg_temp.t_out WHERE k = 'wal_start'))::pg_lsn)));
  RAISE EXCEPTION 'T4263_RESULT %', (SELECT jsonb_object_agg(k, v) FROM pg_temp.t_out);
END
$end4263n$;
